let _wlsResult=null;document.addEventListener("DOMContentLoaded",()=>{document.getElementById("wlsCheckBtn").addEventListener("click",runLookup),document.getElementById("wlsEmail").addEventListener("keydown",e=>{e.key==="Enter"&&runLookup()}),document.querySelectorAll("[data-open-message]").forEach(e=>e.addEventListener("click",openMessageForm)),document.getElementById("wlsCancelMsgBtn").addEventListener("click",closeMessageForm),document.getElementById("wlsSendMsgBtn").addEventListener("click",sendMessage)});function showState(e){document.getElementById("wlsEmpty").classList.toggle("hidden",e!=="empty"),document.getElementById("wlsNotFound").classList.toggle("hidden",e!=="notfound"),document.getElementById("wlsFound").classList.toggle("hidden",e!=="found")}async function runLookup(){const e=document.getElementById("wlsEmail").value.trim();if(!e)return;closeMessageForm(),hideToast();const n=document.getElementById("wlsCheckBtn");n.disabled=!0,n.textContent="Checking\u2026";try{const t=await lookupWaitlistStatus(e);t&&t.found?(_wlsResult=t,renderFound(t),showState("found")):(_wlsResult=null,showState("notfound"))}catch(t){_wlsResult=null,showState("notfound")}finally{n.disabled=!1,n.textContent="Check Status"}}function renderFound(e){document.getElementById("wlsChildName").textContent=e.childName,document.getElementById("wlsRoomLabel").textContent=e.roomLabel;const n=document.getElementById("wlsStatusPill");let t,l;e.position===1?(t="Next in line!",l="wls-status-green"):e.position<=Math.ceil(e.totalInLine/2)?(t="Almost there!",l="wls-status-green"):(t="Waiting",l="wls-status-amber"),n.textContent=t,n.className=`wls-status-pill ${l}`,document.getElementById("wlsPositionLabel").textContent=`#${e.position} of ${e.totalInLine}`;const s=Math.round((e.totalInLine-e.position+1)/e.totalInLine*100);document.getElementById("wlsProgressFill").style.width=`${s}%`,document.getElementById("wlsWaitRange").textContent=e.waitRange,document.getElementById("wlsSiblingNote").classList.toggle("hidden",!e.hasSibling),document.getElementById("wlsDesiredStart").textContent=e.desiredStart,document.getElementById("wlsDays").textContent=e.days,document.getElementById("wlsSchedule").textContent=e.schedule}function openMessageForm(){hideToast(),document.getElementById("wlsMessageForm").classList.remove("hidden")}function closeMessageForm(){document.getElementById("wlsMessageForm").classList.add("hidden"),document.getElementById("wlsMsgText").value=""}function hideToast(){document.getElementById("wlsToast").classList.add("hidden")}async function sendMessage(){const e=document.getElementById("wlsMsgText").value.trim();if(!e){closeMessageForm();return}const n=document.getElementById("wlsEmail").value.trim(),t=document.getElementById("wlsSendMsgBtn");t.disabled=!0,t.textContent="Sending\u2026";try{await addMessage({parentName:_wlsResult?`${_wlsResult.childName}'s family`:"",parentEmail:n,message:`[Waitlist Status] ${e}`})}catch(l){const s=encodeURIComponent("Waitlist Status Question"),d=encodeURIComponent(`Email: ${n}

${e}`);window.location.href=`mailto:?subject=${s}&body=${d}`}finally{t.disabled=!1,t.textContent="Send"}closeMessageForm(),document.getElementById("wlsToast").classList.remove("hidden")}
